  identityHint=text("",15);status=text("",16);automatic=new Switch(this);automatic.setText(t("Automatically send diagnostics (optional)","إرسال التشخيص تلقائيًا (اختياري)"));body.addView(automatic);automatic.setOnClickListener(v->{boolean on=automatic.isChecked();automatic.setChecked(!on);if(on)consent(()->SupportReporter.changeConsent(true,s->refresh()));else SupportReporter.changeConsent(false,s->refresh());});
