  String privacy=t("Only technical events, timing/counters, device model and app/system versions are sent to the developer's Supabase database in Frankfurt. No watched titles, searches, URLs, account details, passwords, cookies, location or phone identifiers. Supabase receives your IP to handle the connection; we do not store it in diagnostic reports. The support ID is random and shared with official MM Auto, Tube and IPTV in the same Android profile when MM Auto is available. It links their reports, including earlier reports from this installation, when you send a report or automatic diagnostics is enabled in each app. App updates keep it. No IMEI, Android ID or phone number is used. Clearing all app data may create a new ID.","يُرسل فقط أحداث تقنية وأوقات وأرقام أداء وموديل الجهاز وإصدارات التطبيق والنظام إلى قاعدة بيانات المطور على Supabase في فرانكفورت. لا تُرسل عناوين المشاهدة أو البحث أو الروابط أو بيانات الحساب أو كلمات السر أو الكوكيز أو الموقع أو معرفات الهاتف. Supabase يستقبل عنوان IP لتوصيل الطلب؛ لا نخزنه في التقارير. رقم الدعم عشوائي ومشترك بين تطبيقات MM Auto وTube وIPTV الرسمية في نفس ملف مستخدم Android عند توفر MM Auto. يربط تقاريرها ومنها التقارير السابقة لهذا التثبيت عند إرسال تقرير أو أثناء تفعيل التشخيص التلقائي في كل تطبيق. تحديث التطبيقات لا يغيّره. لا نستخدم IMEI أو Android ID أو رقم الهاتف. مسح بيانات التطبيقات قد ينشئ رقمًا جديدًا.");
  privacy+="\n\n"+t("Automatic sending is on by default after the first-use explanation; a previously saved off setting stays off. You can turn it off anytime here. When enabled, small batches are attempted about every 2 hours, subject to Android battery/network limits. Reports are kept for up to 30 days, possibly less when storage limits are reached. Disabling stops future uploads; use Delete to remove reports already sent. Local safe history: last 24 hours / 256 events. Sending now includes the latest 128 events; it does not enable automatic sending.","الإرسال التلقائي مفعّل افتراضيًا بعد توضيح أول استخدام، مع الحفاظ على أي إعداد إيقاف محفوظ سابقًا. يمكنك إيقافه هنا في أي وقت. عند تفعيله تُرسل دفعات صغيرة كل ساعتين تقريبًا حسب قيود البطارية والشبكة. تُحفظ التقارير حتى ٣٠ يومًا وقد تُحذف أبكر عند بلوغ حدود التخزين. الإيقاف يمنع الإرسال القادم؛ استخدم الحذف لإزالة التقارير المرسلة. السجل الآمن المحلي: آخر ٢٤ ساعة / ٢٥٦ حدثًا. إرسال الآن يشمل آخر ١٢٨ حدثًا ولا يفعّل الإرسال التلقائي.");
  final String policy=privacy; text(t("Used only to diagnose problems and improve the app. Technical events, device/software details and a shared support ID; no account or watched-content data. You can turn automatic sharing off above.","لإصلاح المشاكل وتحسين التطبيق فقط: أحداث تقنية ومعلومات الجهاز والبرامج ورقم الدعم المشترك. بدون بيانات الحساب أو محتوى المشاهدة. يمكنك إيقاف المشاركة من الزر أعلاه."),15);button(t("Privacy & retention","الخصوصية ومدة الاحتفاظ"),()->new AlertDialog.Builder(this).setTitle(t("Privacy","الخصوصية")).setMessage(policy).setPositiveButton(t("Close","إغلاق"),null).show());
  LinearLayout main=body;LinearLayout advanced=new LinearLayout(this);advanced.setOrientation(LinearLayout.VERTICAL);advanced.setVisibility(android.view.View.GONE);button(t("Advanced options","خيارات متقدمة"),()->advanced.setVisibility(advanced.getVisibility()==android.view.View.VISIBLE?android.view.View.GONE:android.view.View.VISIBLE));main.addView(advanced);body=advanced;
  button(t("Share a report manually","مشاركة تقرير يدويًا"),()->SupportReporter.share(this,false));button(t("Copy report","نسخ التقرير"),()->SupportReporter.share(this,true));
  button(t("Delete this app’s reports","حذف تقارير هذا التطبيق"),()->new AlertDialog.Builder(this).setMessage(t("Stops automatic sending and deletes this app installation’s reports after server confirmation. Other apps’ reports and the shared support ID remain unchanged. Internet is required. Saved exports are unaffected.","يوقف الإرسال ويحذف تقارير تثبيت هذا التطبيق بعد تأكيد الخادم. تقارير التطبيقات الأخرى ورقم الدعم المشترك لا تتغير. يلزم الإنترنت. الملفات المصدرة لا تتأثر.")).setPositiveButton(t("Delete","حذف"),(d,w)->{busy=true;SupportReporter.erase(s->{busy=false;refresh();Toast.makeText(this,message(s),android.widget.Toast.LENGTH_LONG).show();});}).setNegativeButton(t("Cancel","إلغاء"),null).show());
  button(t("Advanced: local log sessions","متقدم: جلسات اللوج المحلية"),()->startActivity(new Intent(this,DiagnosticsActivity.class).putExtra("language",ar?"ar":"en")));body=main;button(t("Back","رجوع"),this::finish);refresh();
