 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)SupportNotice.show(this,ar,this::refresh);}
 @Override protected void onResume(){super.onResume();if(id!=null)refresh();}
 private void consent(Runnable action){new AlertDialog.Builder(this).setTitle(t("Share technical diagnostics?","مشاركة التشخيص التقني؟")).setMessage(t("Share technical reports to help fix problems? They include device information and your support ID, without passwords or watched content. You can turn off automatic sharing anytime here.","مشاركة تقارير تقنية للمساعدة في حل المشاكل؟ تشمل معلومات الجهاز ورقم الدعم، بدون كلمات المرور أو محتوى المشاهدة. يمكنك إيقاف المشاركة التلقائية هنا في أي وقت.")).setPositiveButton(t("Agree","موافق"),(d,w)->action.run()).setNegativeButton(t("Cancel","إلغاء"),null).show();}
 private void refresh(){SupportReporter.info(j->{if(isFinishing()||isDestroyed())return;supportId=j.optString("support_id");id.setText(t("Support ID: ","رقم الدعم: ")+supportId);identityHint.setText(j.optBoolean("shared")?t("Shared across MM apps on this phone. Updates keep this ID.","مشترك بين تطبيقات MM على هذا الموبايل. التحديث لا يغيّر الرقم."):t("App-only ID. Install or update MM Auto to use one ID across MM apps.","رقم خاص بهذا التطبيق. ثبّت أو حدّث MM Auto لتوحيد الرقم بين التطبيقات."));automatic.setChecked(j.optBoolean("enabled"));long sent=j.optLong("last_sent");status.setText(message(j.optString("status"))+(sent>0?"\n"+t("Last delivered: ","آخر وصول ناجح: ")+java.text.DateFormat.getDateTimeInstance().format(new java.util.Date(sent)):""));});}
 private String message(String s){switch(s){case "sent":return t("Report delivered. Share your support ID with the developer.","وصل التقرير. ابعت رقم الدعم للمطور.");case "deleted":return t("This app’s reports were deleted.","تم حذف تقارير هذا التطبيق.");case "limit":return t("Service limit reached. Try later or share manually.","وصلنا لحد الخدمة. جرّب لاحقًا أو شارك يدويًا.");case "failed":return t("Not delivered. Check internet; try again or share manually.","التقرير لم يصل. افحص الإنترنت وجرّب تاني أو شارك يدويًا.");default:return t("No report sent yet.","لم يتم إرسال تقرير بعد.");}}
 private TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setPadding(0,12,0,12);body.addView(v);return v;}
 private void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);body.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{if(!busy)r.run();});}
